using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Observer.WindowAlgebra;

internal sealed class DynamicalObservableKernelDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The real algebra generated by iterated readouts has the complete-itinerary kernel.",
        H("Dynamical Observable Kernel"),
        Blocks(
            Describe.Lean(
                DescribeId.Create("generated-real-observables-have-the-future-readout-kernel"),
                DeclarationHandle.Create(
                    "D5/S3/Observer/WindowAlgebra/DynamicalObservableKernel."
                        + "dynamical_observable_kernel"),
                H("Generated observables recover complete future behavior"),
                StatementSource.FromAuthor(KernelFormula()),
                AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text(
                        "For arbitrary state and output carriers, the observable algebra is "
                            + "constructed publicly as the real subalgebra generated by every "
                            + "real function of a range-factorized readout after a finite iterate "
                            + "of the update.")),
                    Paragraph(Text(
                        "Equal complete itineraries make each generator, hence every algebraic "
                            + "combination of generators, agree. Conversely, when a future "
                            + "readout differs, a real indicator on the actual readout range "
                            + "separates the two states at that iterate.")),
                    Paragraph(Text(
                        "The canonical completeItinerary and rangeFactorization primitives are "
                            + "reused. Repository and pinned-Mathlib searches found no exact "
                            + "real-carrier dynamical algebra theorem; the nearby frozen theorem "
                            + "uses a complex star algebra and is not coverage for this carrier."))),
                DescribeRole.Theorem))));

    private static Formula Call(string name, params Formula[] arguments)
    {
        var items = new List<Formula> { Operatorname, Grp(F.Id(name)), Open };
        for (var index = 0; index < arguments.Length; index++)
        {
            if (index > 0) items.AddRange([Comma, Sp]);
            items.Add(arguments[index]);
        }

        items.Add(Close);
        return Seq([.. items]);
    }

    private static Formula KernelFormula()
    {
        Formula state = F.Id("Y");
        Formula output = F.Id("O");
        Formula update = Tau;
        Formula readout = F.Id("q");
        Formula real = Seq(Mathbb, Grp(F.Id("R")));
        Formula naturals = Seq(Mathbb, Grp(F.Id("N")));
        Formula index = F.Id("n");
        Formula postprocess = F.Id("h");
        Formula function = F.Id("f");
        Formula first = F.Id("x");
        Formula second = F.Id("y");
        Formula algebra = Seq(F.Id("A"), Underscore, Grp(Infty));
        Formula range = Call("range", readout);
        Formula generator = Seq(
            postprocess, Sp, Circ, Sp, Call("rangeFactorization", readout),
            Sp, Circ, Sp, Call("iterate", update, index));
        Formula generators = Seq(
            OpenBrace, generator, Sp, Bar, Sp,
            index, Sp, InMacro, Sp, naturals, Comma, Sp,
            postprocess, Colon, Sp, new Formula.TypeArrow(range, real), CloseBrace);
        Formula functionType = new Formula.TypeArrow(state, real);
        Formula algebraType = Call("Subalgebra", real, functionType);
        Formula agreement = Seq(
            Forall, Sp, function, Colon, Sp, functionType, Comma, Sp,
            function, Sp, InMacro, Sp, algebra, Sp, Rightarrow, Sp,
            function, Open, first, Close, Sp, Eq, Sp,
            function, Open, second, Close);
        Formula sameItinerary = Seq(
            Call("completeItinerary", update, readout, first), Sp, Eq, Sp,
            Call("completeItinerary", update, readout, second));

        return Disp(Seq(
            Begin, Grp(F.Id("gathered")),
            Forall, Sp, state, Comma, Sp, output, Colon, Sp,
            Operatorname, Grp(F.Id("Type")), Comma, RowBreak, Grp(),
            update, Colon, Sp, new Formula.TypeArrow(state, state), Comma, Sp,
            readout, Colon, Sp, new Formula.TypeArrow(state, output), Comma, RowBreak, Grp(),
            algebra, Colon, Sp, algebraType, Sp, Colon, Eq, Sp,
            Call("adjoin", real, generators), Comma, RowBreak, Grp(),
            Forall, Sp, first, Comma, Sp, second, Colon, Sp, state, Comma, Sp,
            Open, agreement, Close, Sp, Leftrightarrow, Sp,
            Open, sameItinerary, Close, Dot,
            End, Grp(F.Id("gathered"))));
    }
}
